const savedAccountsStorageKey='social-land-saved-accounts'
const readSavedAccounts=():SavedAccount[]=>{try{const value=JSON.parse(localStorage.getItem(savedAccountsStorageKey)||'[]');return Array.isArray(value)?value.filter((item):item is SavedAccount=>!!item&&typeof item.id==='string'&&typeof item.username==='string'&&typeof item.displayName==='string'&&typeof item.token==='string'&&!!item.token).slice(0,10):[]}catch{return []}}
const writeSavedAccounts=(accounts:SavedAccount[])=>{try{localStorage.setItem(savedAccountsStorageKey,JSON.stringify(accounts.slice(0,10)))}catch{}}

