async function api<T>(path:string, token:string, options:RequestInit={}):Promise<T>{const res=await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{ }),...options.headers}});const body=await res.json().catch(()=>({}));if(!res.ok)throw new Error(body.error||`Request failed (${res.status})`);return body as T}

async function apiForm<T>(path:string,token:string,form:FormData):Promise<T>{const res=await fetch(`/api${path}`,{method:'POST',headers:token?{Authorization:`Bearer ${token}`}:{},body:form});const body=await res.json().catch(()=>({}));if(!res.ok)throw new Error(body.error||`Request failed (${res.status})`);return body as T}function apiFormWithProgress<T>(path:string,token:string,form:FormData,onProgress:(percent:number)=>void):Promise<T>{return new Promise((resolve,reject)=>{const request=new XMLHttpRequest();request.open('POST',`/api${path}`);if(token)request.setRequestHeader('Authorization',`Bearer ${token}`);request.upload.onprogress=event=>{if(event.lengthComputable)onProgress(Math.round(event.loaded/event.total*100))};request.onload=()=>{let body:any={};try{body=JSON.parse(request.responseText||'{}')}catch{}if(request.status<200||request.status>=300){reject(new Error(body.error||`Request failed (${request.status})`));return}resolve(body as T)};request.onerror=()=>reject(new Error('Network error while sending your file.'));request.onabort=()=>reject(new Error('File transfer was cancelled.'));request.send(form)})}

const initials=(s:string)=>s.split(/[\s@._-]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()

const activityMessage=(activity:Activity)=>{const who=activity.actor.displayName;switch(activity.type){case'friend_request':return `${who} sent you a friend request`;case'friend_accepted':return `${who} accepted your friend request`;case'follow_request':return `${who} requested to follow you`;case'like':return `${who} liked your post`;case'comment':return `${who} commented on your post`;case'share':return `${who} shared your post`;case'message':return `${who} sent you a message`;case'story_like':return `${who} liked your story`}}

const lastSeenLabel=(user:User,onlineUserIds:string[])=>{if(onlineUserIds.includes(user.id))return 'Online now';if(!user.lastSeenAt)return 'Last seen unavailable';const date=new Date(user.lastSeenAt);if(Number.isNaN(date.getTime()))return 'Last seen unavailable';const today=new Date();const yesterday=new Date(today);yesterday.setDate(today.getDate()-1);const day=date.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});if(date.toDateString()===today.toDateString())return `Last seen today at ${day}`;if(date.toDateString()===yesterday.toDateString())return `Last seen yesterday at ${day}`;return `Last seen ${date.toLocaleDateString([],{month:'short',day:'numeric'})}`}

