const chatTextColor=(hex:string)=>{const red=parseInt(hex.slice(1,3),16),green=parseInt(hex.slice(3,5),16),blue=parseInt(hex.slice(5,7),16);return (red*299+green*587+blue*114)/1000>150?'#34323f':'#ffffff'}
const colors=['lilac','peach','mint','blue'];const avatarColor=(s:string)=>colors[(s.charCodeAt(0)||0)%colors.length]

const youtubeIdFrom=(value:string)=>{try{const u=new URL(value);const host=u.hostname.toLowerCase().replace(/^www\./,'');if(host==='youtu.be')return u.pathname.slice(1).split('/')[0]||null;if(['youtube.com','m.youtube.com','music.youtube.com','youtube-nocookie.com'].includes(host)){const id=u.searchParams.get('v');if(id)return id;const match=u.pathname.match(/^\/(?:embed|shorts|live)\/([^/?]+)/);return match?.[1]||null}}catch{return null}return null}

const partyEmbedUrlFrom=(value:string)=>{try{const u=new URL(value);const host=u.hostname.toLowerCase().replace(/^www\./,'');let match:RegExpMatchArray|null=null;if(host==='vimeo.com'||host==='player.vimeo.com'){match=u.pathname.match(/\/(?:video\/)?(\d+)/);if(match)return `https://player.vimeo.com/video/${match[1]}?dnt=1`}if(host==='dailymotion.com'||host==='m.dailymotion.com'){match=u.pathname.match(/\/video\/([a-zA-Z0-9]+)/);if(match)return `https://www.dailymotion.com/embed/video/${match[1]}`}if(host==='dai.ly'){match=u.pathname.match(/^\/([a-zA-Z0-9]+)/);if(match)return `https://www.dailymotion.com/embed/video/${match[1]}`}}catch{}return null}
const isNetflixUrl=(value:string)=>{try{const host=new URL(value).hostname.toLowerCase();return host==='netflix.com'||host.endsWith('.netflix.com')}catch{return false}}
const isDirectVideoUrl=(value:string)=>{try{return /\.(?:mp4|m4v|webm|ogv)$/i.test(new URL(value).pathname)}catch{return false}}

const loadYouTubeApi=()=>new Promise<YouTubeApi>((resolve,reject)=>{if(window.YT?.Player){resolve(window.YT);return}const previous=window.onYouTubeIframeAPIReady;const timeout=window.setTimeout(()=>reject(new Error('YouTube player could not load. Check your connection and try again.')),12000);window.onYouTubeIframeAPIReady=()=>{previous?.();window.clearTimeout(timeout);if(window.YT)resolve(window.YT);else reject(new Error('YouTube player did not initialize.'))};if(!document.getElementById('youtube-iframe-api')){const script=document.createElement('script');script.id='youtube-iframe-api';script.src='https://www.youtube.com/iframe_api';script.async=true;script.onerror=()=>{window.clearTimeout(timeout);reject(new Error('Could not load the YouTube player.'))};document.head.appendChild(script)}})

const requestCallMedia=(mode:'audio'|'video'='video')=>{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Calls require HTTPS or localhost so the browser can access your microphone.');return navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:mode==='video'?{width:{ideal:640,max:854},height:{ideal:360,max:480},frameRate:{ideal:20,max:24}}:false})}
const requestLiveMedia=async()=>{if(!navigator.mediaDevices?.getUserMedia)throw new Error('This browser blocks camera and microphone access on this HTTP address. Open http://localhost:5173 on this computer, or use HTTPS / a browser insecure-origin testing override for LAN testing.');const constraints:MediaStreamConstraints={audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:{width:{ideal:640,max:854},height:{ideal:360,max:480},frameRate:{ideal:20,max:24}}};try{return await navigator.mediaDevices.getUserMedia(constraints)}catch(error){if(error instanceof DOMException&&['OverconstrainedError','NotFoundError'].includes(error.name))return navigator.mediaDevices.getUserMedia({audio:true,video:{width:{ideal:640},height:{ideal:360},frameRate:{ideal:20}}});throw error}}
const addLiveTracks=(peer:RTCPeerConnection,stream:MediaStream)=>stream.getTracks().forEach(track=>{const sender=peer.addTrack(track,stream);if(track.kind==='video'){const params=sender.getParameters();params.encodings=params.encodings?.length?params.encodings:[{}];params.encodings[0].maxBitrate=450000;params.encodings[0].maxFramerate=20;void sender.setParameters(params).catch(()=>{})}})

const profileImageFromFile=async(file:File)=>{if(!file.type.startsWith('image/'))throw new Error('Choose an image file.');if(file.size>8*1024*1024)throw new Error('Choose an image smaller than 8 MB.');const image=await createImageBitmap(file);const scale=Math.min(1,512/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext('2d');if(!context)throw new Error('Could not prepare this image.');context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);image.close();return canvas.toDataURL('image/jpeg',0.8)}
const profileBannerFromFile=async(file:File)=>{if(!file.type.startsWith('image/'))throw new Error('Choose an image file.');if(file.size>8*1024*1024)throw new Error('Choose an image smaller than 8 MB.');const image=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=1280;canvas.height=420;const scale=Math.max(canvas.width/image.width,canvas.height/image.height);const width=image.width*scale,height=image.height*scale;const context=canvas.getContext('2d');if(!context)throw new Error('Could not prepare this banner.');context.drawImage(image,(canvas.width-width)/2,(canvas.height-height)/2,width,height);image.close();return canvas.toDataURL('image/jpeg',0.82)}

