const postFilterCss=(id:string,strength:number)=>{const source=postFilters.find(item=>item.id===id)?.css||'none';if(source==='none')return source;const amount=Math.max(0,Math.min(100,strength))/100;if(amount===1)return source;const neutral:Record<string,{value:number;unit:string}>={grayscale:{value:0,unit:''},sepia:{value:0,unit:''},invert:{value:0,unit:''},opacity:{value:1,unit:''},saturate:{value:1,unit:''},brightness:{value:1,unit:''},contrast:{value:1,unit:''},blur:{value:0,unit:'px'},'hue-rotate':{value:0,unit:'deg'}};return source.replace(/([a-z-]+)\(([-\d.]+)(%|deg|px)?\)/g,(whole,name,raw,unit='')=>{const base=neutral[name];if(!base)return whole;const value=Number(raw),normalizedUnit=unit||base.unit,neutralValue=base.unit==='%'?100:base.value,adjusted=neutralValue+(value-neutralValue)*amount;return `${name}(${Number(adjusted.toFixed(3))}${normalizedUnit})`})}
const cropSource=(width:number,height:number,ratio:number,zoom:number)=>{if(!ratio)return{x:0,y:0,width,height};let cropWidth=width,cropHeight=height;if(width/height>ratio)cropWidth=height*ratio;else cropHeight=width/ratio;cropWidth/=zoom;cropHeight/=zoom;return{x:(width-cropWidth)/2,y:(height-cropHeight)/2,width:cropWidth,height:cropHeight}}
