 const removeProfileConnection=async(user:User)=>{const kind=followListDialog?.kind;if(!kind||!isOwnProfile)return;const action=kind==='following'?'unfollow':kind==='followers'?'remove this follower':'unfriend';const confirmed=await requestPrompt({title:`${action[0].toUpperCase()+action.slice(1)} ${user.displayName}?`,description:kind==='friends'?`You and ${user.displayName} will no longer be friends. Your existing chat will remain.`:`${user.displayName} will be removed from your ${kind} list.`,confirmLabel:kind==='friends'?'Unfriend':kind==='following'?'Unfollow':'Remove follower',cancelLabel:'Keep',input:false,danger:true});if(confirmed===null)return;try{await api(kind==='friends'?`/friends/${user.id}`:kind==='following'?`/users/${user.id}/follow`:`/users/${profileOwner.id}/follower`,token,{method:'DELETE'});setFollowListDialog(current=>current?{...current,users:current.users.filter(item=>item.id!==user.id)}:current);const update=(owner:User)=>({...owner,followerCount:Math.max(0,(owner.followerCount||0)-(kind==='followers'?1:0)),followingCount:Math.max(0,(owner.followingCount||0)-(kind==='following'?1:0)),friendCount:Math.max(0,(owner.friendCount||0)-(kind==='friends'?1:0))});if(profileOwner.id===me.id)setMe(current=>current?update(current):current);else setViewedProfile(current=>current?{...current,user:update(current.user)}:current);if(kind==='friends'){setFriends(current=>current.filter(item=>item.id!==user.id));if(activeChat?.user.id===user.id&&messagePrivacy==='friends'&&user.messagePrivacy!=='everyone'){setActiveChat(chat=>chat?{...chat,unavailable:true}:chat);setChats(items=>items.map(chat=>chat.user.id===user.id?{...chat,unavailable:true}:chat))}}show(kind==='friends'?`${user.displayName} removed from your friends.`:kind==='following'?`You unfollowed ${user.displayName}.`:`${user.displayName} removed from your followers.`)}catch(error){show((error as Error).message||`Could not ${action} this person.`)}}

 const blockProfileUser=async()=>{const target=profileOwner;if(isOwnProfile||target.blockedProfile)return;const confirmed=await requestPrompt({title:`Block ${target.displayName}?`,description:`They will not be able to message or call you or view your profile. Your friendship and follow connection will be removed.`,confirmLabel:'Block account',cancelLabel:'Cancel',danger:true});if(confirmed===null)return;try{await api('/users/'+target.id+'/block',token,{method:'POST',body:JSON.stringify({blocked:true})});setViewedProfile(current=>current?.user.id===target.id?{...current,user:{...current.user,blockedProfile:true}}:current);setOnlineUserIds(ids=>ids.filter(id=>id!==target.id));setTypingUsers(items=>items.filter(user=>user.id!==target.id));setTypingByConversation(items=>{const next={...items};for(const chat of chatsRef.current)if(chat.user.id===target.id)delete next[chat.id];return next});void loadFriends();void loadChats();show(`${target.displayName} is blocked. They cannot message, call, or view your profile.`)}catch(error){show((error as Error).message||'Could not block this account.')}};const confirmDeleteBlockedChat=async()=>{if(!activeChat||!activeChat.blocked||blockActionLoading)return;const chat=activeChat;setBlockActionLoading(true);try{await api(`/conversations/${chat.id}`,token,{method:'DELETE',body:JSON.stringify({action:'delete'})});setChats(items=>items.filter(item=>item.id!==chat.id));setActiveChat(null);setChatViewOpen(false);setMessages([]);setChatMenuId(null);setDeleteBlockedChatConfirm(false);show('Chat deleted for you.')}catch(error){show((error as Error).message||'Could not delete this chat.')}finally{setBlockActionLoading(false)}}
 const confirmBlockAction=async()=>{if(!activeChat||activeChat.isGroup||blockActionLoading)return;const blocked=!activeChat.blocked;setBlockActionLoading(true);try{const result=await api<{blocked:boolean;needsReconnect?:boolean}>(`/users/${activeChat.user.id}/block`,token,{method:'POST',body:JSON.stringify({blocked})});setChats(items=>items.map(chat=>chat.id===activeChat.id?{...chat,blocked:result.blocked,unavailable:result.blocked||!!result.needsReconnect,needsReconnect:!!result.needsReconnect}:chat));setActiveChat(chat=>chat?{...chat,blocked:result.blocked,unavailable:result.blocked||!!result.needsReconnect,needsReconnect:!!result.needsReconnect}:chat);if(result.blocked){if(locationConversationRef.current===activeChat.id)stopLiveLocation(activeChat.id);setOnlineUserIds(ids=>ids.filter(id=>id!==activeChat.user.id));setTypingUsers(items=>items.filter(user=>user.id!==activeChat.user.id));setTypingByConversation(items=>{const next={...items};delete next[activeChat.id];return next})}setBlockConfirmOpen(false);setChatDetailsOpen(false);show(result.blocked?`${activeChat.user.displayName} is blocked. They cannot message, call, or view your profile.`:result.needsReconnect?`${activeChat.user.displayName} is unblocked. Send and accept a new friend request to reconnect.`:`${activeChat.user.displayName} is unblocked.`)}catch(error){show((error as Error).message||'Could not update block settings.')}finally{setBlockActionLoading(false)}}
