  const selectChatMedia=(file?:File)=>{if(!file)return;const allowed=['image/jpeg','image/png','image/webp','video/mp4','video/webm','video/quicktime','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','text/plain','text/csv','application/rtf','text/rtf','application/vnd.oasis.opendocument.text','application/vnd.oasis.opendocument.spreadsheet','application/vnd.oasis.opendocument.presentation','application/zip'];const extension=file.name.toLowerCase().split('.').pop()||'';const supportedExtensions=['jpg','jpeg','png','webp','mp4','webm','mov','pdf','doc','docx','xls','xlsx','ppt','pptx','txt','csv','rtf','odt','ods','odp','zip'];if(!allowed.includes(file.type)&&!supportedExtensions.includes(extension)){show('Choose an image, video, PDF, Office document, text, CSV, or ZIP file.');return}if(file.size>50*1024*1024){show('Choose a file smaller than 50 MB.');return}const isPreviewable=file.type.startsWith('image/')||file.type.startsWith('video/')||['jpg','jpeg','png','webp','mp4','webm','mov'].includes(extension);setChatMediaFile(file);setChatMediaPreview(isPreviewable?URL.createObjectURL(file):'');setChatAttachOpen(false)}
