  const selectChatBackground=async(file?:File)=>{if(!file)return;try{const image=await profileImageFromFile(file);setCustomChatBackground(image);setChatTheme('custom');setChatThemeOpen(false)}catch(error){show(error instanceof Error?error.message:'Could not use this background image.')}}

