 const completePasswordResetFromSettings=async(e:FormEvent)=>{e.preventDefault();if(newPassword!==confirmPassword){show('The new passwords do not match.');return}try{const d=await api<{token:string;user:User}>('/auth/reset-password','',{method:'POST',body:JSON.stringify({email:me.email,code:passwordResetCode,password:newPassword})});localStorage.setItem('looply-token',d.token);setToken(d.token);setMe({...d.user,bannerUrl:me.bannerUrl});rememberAccount({id:d.user.id,username:d.user.username,displayName:d.user.displayName,avatarUrl:d.user.avatarUrl||'',token:d.token});setPasswordResetStep(false);setPasswordResetCode('');setNewPassword('');setConfirmPassword('');setChangingPassword(false);show('Password reset. Other sessions were signed out.')}catch(e){show((e as Error).message)}}
