 const changePassword=async(e:FormEvent)=>{e.preventDefault();if(newPassword!==confirmPassword){show('The new passwords do not match.');return}try{const d=await api<{token:string;user:User}>('/auth/change-password',token,{method:'POST',body:JSON.stringify({currentPassword,newPassword})});localStorage.setItem('looply-token',d.token);setToken(d.token);setMe({...d.user,bannerUrl:me.bannerUrl});rememberAccount({id:d.user.id,username:d.user.username,displayName:d.user.displayName,avatarUrl:d.user.avatarUrl||'',token:d.token});setCurrentPassword('');setNewPassword('');setConfirmPassword('');setChangingPassword(false);show('Password changed. Other sessions were signed out.')}catch(e){show((e as Error).message)}}

 const createPost=async(e:FormEvent)=>{e.preventDefault();if(publishing)return;if(postKind==='post'&&!postFiles.length){show('Add at least one photo or video to publish a post. For text only, share a Note.');return}if(postKind==='reel'&&(postFiles.length!==1||!postFiles[0].type.startsWith('video/'))){show('Choose one video to publish a Reel.');return}if(postKind==='note'&&(!postCaption.trim()||postFiles.length)){show('Notes are text-only and need some text.');return}if(postFiles.length>10||postFiles.reduce((total,file)=>total+file.size,0)>200*1024*1024){show('A post can contain up to 10 media files and 200 MB total.');return}const form=new FormData();form.append('caption',postCaption);form.append('kind',postKind);setPublishing(true);try{const editedFiles=await Promise.all(postFiles.map((file,index)=>{const ratio=postKind==='reel'?0:(postAspectRatios.find(item=>item.id===postCropRatio)?.value||0);const filter=postFilterByIndex[index]||'original';return file.type.startsWith('video/')?transformVideoForPost(file,ratio,postCropZoom,filter,postFilterStrength,postVideoTrims[index]?.start||0,postVideoTrims[index]?.end??Math.min(60,postVideoDurations[index]||60)):transformImageForPost(file,ratio,postCropZoom,filter,postFilterStrength)}));if(editedFiles.some(file=>file.size>50*1024*1024)||editedFiles.reduce((total,file)=>total+file.size,0)>200*1024*1024)throw new Error('Edited files must stay under 50 MB each and 200 MB total.');editedFiles.forEach(file=>form.append('media',file));const created=await apiForm<{post:SocialPost}>('/posts',token,form);setPostCaption('');setPostFiles([]);setComposerMediaIndex(0);setPostFilterByIndex({});setPostVideoTrims({});setPostVideoDurations({});setPostCropZoom(1);if(postKind==='note')setProfileNotes(items=>[{id:created.post.id,authorId:me.id,text:created.post.caption,createdAt:created.post.createdAt,legacy:false},...items]);else await loadSocialPosts(postKind);show(postKind==='reel'?'Your Reel is live!':postKind==='note'?'Your note is live!':'Your post is live!')}catch(e){show((e as Error).message)}finally{setPublishing(false)}}

 const toggleLike=async(post:SocialPost)=>{try{const d=await api<{liked:boolean;likesCount:number}>(`/posts/${post.id}/like`,token,{method:'POST'});const update=(items:SocialPost[])=>items.map(p=>p.id===post.id?{...p,likedByMe:d.liked,likesCount:d.likesCount}:p);setPosts(update);setReels(update)}catch(e){show((e as Error).message)}}

 const togglePostComments=async(post:SocialPost)=>{const opening=!openComments[post.id];setOpenComments(v=>({...v,[post.id]:opening}));if(opening&&!commentsByPost[post.id])try{const d=await api<{comments:SocialComment[]}>(`/posts/${post.id}/comments`,token);setCommentsByPost(v=>({...v,[post.id]:d.comments}))}catch(e){show((e as Error).message)}}

 const submitComment=async(e:FormEvent,post:SocialPost,parentCommentId?:string)=>{e.preventDefault();if(commentSubmitting.current.has(post.id))return;const text=(commentDrafts[post.id]||'').trim();if(!text)return;commentSubmitting.current.add(post.id);setCommentSending(v=>({...v,[post.id]:true}));try{const d=await api<{comment:SocialComment}>(`/posts/${post.id}/comments`,token,{method:'POST',body:JSON.stringify({text,...(parentCommentId?{parentCommentId}:{})})});setCommentsByPost(v=>({...v,[post.id]:[...(v[post.id]||[]),d.comment]}));setCommentDrafts(v=>({...v,[post.id]:''}));const update=(items:SocialPost[])=>items.map(p=>p.id===post.id?{...p,commentCount:p.commentCount+1}:p);setPosts(update);setReels(update)}catch(e){show((e as Error).message)}finally{commentSubmitting.current.delete(post.id);setCommentSending(v=>({...v,[post.id]:false}))}}

