 const confirmDeleteComment=async()=>{const target=pendingCommentDelete;if(!target||deletingComment)return;setDeletingComment(true);try{const result=await api<{deletedIds:string[];deletedCount:number}>(`/posts/${target.post.id}/comments/${target.comment.id}`,token,{method:'DELETE'});const deleted=new Set(result.deletedIds);setCommentsByPost(v=>({...v,[target.post.id]:(v[target.post.id]||[]).filter(item=>!deleted.has(item.id))}));const update=(items:SocialPost[])=>items.map(item=>item.id===target.post.id?{...item,commentCount:Math.max(0,item.commentCount-result.deletedCount)}:item);setPosts(update);setReels(update);setPendingCommentDelete(null)}catch(error){show((error as Error).message||'Could not delete this comment.')}finally{setDeletingComment(false)}}

 const postShareUrl=(post:SocialPost)=>{const url=new URL('/',window.location.origin);url.searchParams.set('post',post.id);url.searchParams.set('kind',post.kind);return url.toString()}
 const recordPostShare=async(post:SocialPost)=>{const result=await api<{shareCount:number}>(`/posts/${post.id}/share`,token,{method:'POST'});const update=(items:SocialPost[])=>items.map(item=>item.id===post.id?{...item,shareCount:result.shareCount}:item);setPosts(update);setReels(update);setProfileSelectedPost(current=>current?.id===post.id?{...current,shareCount:result.shareCount}:current);setViewedProfile(current=>current?{...current,posts:update(current.posts),reels:update(current.reels)}:current)}
 const sharePost=async(post:SocialPost)=>{setSharePostTarget(post);setShareChatSearch('');setShareChats([]);setShareLoading(true);try{const result=await api<{conversations:Chat[]}>('/conversations',token);setShareChats(result.conversations)}catch(error){show((error as Error).message||'Could not load your chats.')}finally{setShareLoading(false)}}
 const sharePostToChat=async(chat:Chat)=>{const post=sharePostTarget;if(!post||shareSendingChatId)return;setShareSendingChatId(chat.id);const url=postShareUrl(post);const itemLabel=post.kind==='reel'?'a Reel':post.kind==='note'?'a note':'a post';const text=`🔗 Shared ${itemLabel} by ${post.author.displayName}${post.caption?`\n${post.caption.slice(0,600)}`:''}\n${url}`;try{const result=await api<{message:Msg}>(`/conversations/${chat.id}/messages`,token,{method:'POST',body:JSON.stringify({text})});if(activeChat?.id===chat.id){setMessages(items=>items.some(item=>item.id===result.message.id)?items:[...items,result.message]);setChatScrollVersion(version=>version+1)}const updated={...chat,latestText:text,latestAt:result.message.createdAt};setChats(items=>[...items.filter(item=>item.id!==chat.id),updated].sort((first,second)=>new Date(second.latestAt).getTime()-new Date(first.latestAt).getTime()));setActiveChat(current=>current?.id===chat.id?{...current,...updated}:current);setSharePostTarget(null);show(`Shared in ${chat.isGroup?chat.groupName||'group chat':chat.user.displayName}'s chat`);try{await recordPostShare(post)}catch{show('Message sent, but the share count could not be updated.')}}catch(error){show((error as Error).message||'Could not share this item to the chat.')}finally{setShareSendingChatId(null)}}
 const copyPostShareLink=async()=>{if(!sharePostTarget)return;try{await navigator.clipboard.writeText(postShareUrl(sharePostTarget));await recordPostShare(sharePostTarget);setSharePostTarget(null);show('Link copied to clipboard')}catch(error){show((error as Error).message||'Could not copy the link.')}}
 const sharePostExternally=async()=>{if(!sharePostTarget)return;try{if(!navigator.share){await copyPostShareLink();return}await navigator.share({title:'Social Land',text:sharePostTarget.caption||`A ${sharePostTarget.kind} from ${sharePostTarget.author.displayName}`,url:postShareUrl(sharePostTarget)});setSharePostTarget(null)}catch(error){if((error as Error).name!=='AbortError')show((error as Error).message||'Could not share this item.')}}

 const deletePost=async(post:SocialPost)=>{if(await requestPrompt({title:'Delete this post?',description:'This post will be removed from your profile and cannot be restored.',confirmLabel:'Delete post',danger:true,input:false})===null)return;try{await api(`/posts/${post.id}`,token,{method:'DELETE'});setPosts(v=>v.filter(p=>p.id!==post.id));setReels(v=>v.filter(p=>p.id!==post.id));show('Post deleted')}catch(e){show((e as Error).message)}}

 const markNotificationsRead=async(ids?:string[])=>{try{await api('/notifications/read',token,{method:'POST',body:JSON.stringify(ids?{ids}:{})});setNotifications(items=>items.map(item=>!ids||ids.includes(item.id)?{...item,read:true}:item));setUnreadCount(count=>ids?Math.max(0,count-ids.filter(id=>notifications.some(item=>item.id===id&&!item.read)).length):0)}catch(e){show((e as Error).message)}}

