 const openActivity=(activity:Activity)=>{setNotificationsOpen(false);if(activity.postId){const params=new URLSearchParams(window.location.search);params.set('post',activity.postId);params.set('kind',activity.postKind||'post');window.history.replaceState({},'',`${window.location.pathname}?${params}`);setTab(activity.postKind==='reel'?'Reels':'Home')}else if(activity.type==='friend_request'||activity.type==='follow_request'||activity.type==='friend_accepted')setTab('Friends');else if(activity.type==='message'){setActiveChat(null);setChatViewOpen(false);setChatMenuId(null);setTab('Messages')}if(!activity.read)void markNotificationsRead([activity.id])}

 const createPartyVoicePeer=(peerId:string,initiator:boolean)=>{if(partyVoicePeers.current.has(peerId)||!partyVoiceSessionId.current)return;const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});const peer:GameVoicePeer={connection:pc,pending:[]};partyVoicePeers.current.set(peerId,peer);partyVoiceStream.current?.getTracks().forEach(track=>pc.addTrack(track,partyVoiceStream.current!));pc.onicecandidate=event=>{if(event.candidate)socketRef.current?.emit('party:voice:signal',{sessionId:partyVoiceSessionId.current,to:peerId,kind:'ice',data:event.candidate})};pc.ontrack=event=>{if(event.streams[0])setPartyVoiceStreams(items=>({...items,[peerId]:event.streams[0]}))};if(initiator)void pc.createOffer().then(offer=>pc.setLocalDescription(offer).then(()=>socketRef.current?.emit('party:voice:signal',{sessionId:partyVoiceSessionId.current,to:peerId,kind:'offer',data:offer}))).catch(()=>show('Could not connect watch-room voice.'))};partyVoiceCreatePeerRef.current=createPartyVoicePeer;partyVoiceHandleSignalRef.current=payload=>{if(payload.sessionId!==partyVoiceSessionId.current)return;void(async()=>{try{let peer=partyVoicePeers.current.get(payload.from);if(payload.kind==='offer'&&!peer){createPartyVoicePeer(payload.from,false);peer=partyVoicePeers.current.get(payload.from)}if(!peer)return;const pc=peer.connection;if(payload.kind==='offer'){await pc.setRemoteDescription(payload.data);for(const c of peer.pending.splice(0))await pc.addIceCandidate(c);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socketRef.current?.emit('party:voice:signal',{sessionId:payload.sessionId,to:payload.from,kind:'answer',data:answer})}else if(payload.kind==='answer'){await pc.setRemoteDescription(payload.data);for(const c of peer.pending.splice(0))await pc.addIceCandidate(c)}else if(payload.kind==='ice'){if(pc.remoteDescription)await pc.addIceCandidate(payload.data);else peer.pending.push(payload.data)}}catch{show('Voice connection failed.')}})()};const cleanupPartyVoice=(notify=true)=>{if(notify&&partyVoiceSessionId.current)socketRef.current?.emit('party:voice:leave',{sessionId:partyVoiceSessionId.current});partyVoicePeers.current.forEach(peer=>peer.connection.close());partyVoicePeers.current.clear();partyVoiceStream.current?.getTracks().forEach(track=>track.stop());partyVoiceStream.current=null;partyVoiceSessionId.current='';setPartyVoiceStreams({});setPartyVoiceMembers([]);setPartyVoiceState('off');setPartyVoiceMuted(false)};partyVoiceCleanupRef.current=cleanupPartyVoice;const togglePartyVoice=async()=>{if(partyVoiceState!=='off'){cleanupPartyVoice(true);return}if(!partySession)return;try{setPartyVoiceState('connecting');partyVoiceSessionId.current=partySession.id;partyVoiceStream.current=await navigator.mediaDevices.getUserMedia({audio:true});socketRef.current?.emit('party:voice:join',{sessionId:partySession.id});setPartyVoiceState('on')}catch(error){cleanupPartyVoice(false);show(error instanceof Error?error.message:'Allow microphone access for voice chat.')}};const togglePartyVoiceMute=()=>{const muted=!partyVoiceMuted;partyVoiceStream.current?.getAudioTracks().forEach(track=>track.enabled=!muted);setPartyVoiceMuted(muted)};const sendPartyChat=(event:FormEvent)=>{event.preventDefault();const text=partyChatDraft.trim();if(text&&partySession)socketRef.current?.emit('party:chat:send',{sessionId:partySession.id,text});setPartyChatDraft('')}
 const togglePartyFullscreen=async()=>{const target=partyPlayerRef.current;if(!target)return;try{if(document.fullscreenElement===target)await document.exitFullscreen();else await target.requestFullscreen()}catch{show('Fullscreen is unavailable in this browser.')}}
 const partyInviteUserIds=[...new Set([...partyInviteFriends,...chats.filter(chat=>chat.isGroup&&partyInviteGroups.includes(chat.id)).flatMap(chat=>chat.members||[])])].filter(id=>id!==me?.id)
 const startParty=()=>{if(!partyUrl.trim()){show('Add a video link first');return}try{const parsed=new URL(partyUrl);if(parsed.protocol!=='https:')throw new Error()}catch{show('Enter a valid HTTPS video link.');return}if(partySession?.status==='open'){if(partyInviteUserIds.length){socketRef.current?.emit('party:invite:add',{sessionId:partySession.id,userIds:partyInviteUserIds});setPartyInviteFriends([]);setPartyInviteGroups([]);show('Watch room invitations sent in chat.')}return}setPartyStarted(true);socketRef.current?.emit('party:create',{url:partyUrl,userIds:partyInviteUserIds});setPartyInviteFriends([]);setPartyInviteGroups([])}

