function PostCard({post,currentUserId,comments,commentsOpen,commentDraft,onLike,onComments,onComment,onDraft,onLikeComment,onDeleteComment,commentSending,onShare,onDelete,onOpenStory,onOpenProfile,hasStory,storySeen,reel=false}:{post:SocialPost;currentUserId:string;comments:SocialComment[];commentsOpen:boolean;commentDraft:string;onLike:()=>void;onComments:()=>void;onComment:(e:FormEvent,parentCommentId?:string)=>void;onDraft:(value:string)=>void;onLikeComment:(comment:SocialComment)=>void;onDeleteComment:(comment:SocialComment)=>void;commentSending:boolean;onShare:()=>void;onDelete:()=>void;onOpenStory:(id:string)=>void;onOpenProfile?:(username:string)=>void;hasStory:(id:string)=>boolean;storySeen:(id:string)=>boolean;reel?:boolean}) {
  const media=post.mediaItems?.length?post.mediaItems:(post.mediaUrl?[{url:post.mediaUrl,type:post.mediaType}]:[])
  const [mediaIndex,setMediaIndex]=useState(0)
  const [replyTarget,setReplyTarget]=useState<SocialComment|null>(null)
  const [commentMenuId,setCommentMenuId]=useState<string|null>(null)
  const touchStart=useRef<number|null>(null)
  const moveMedia=(step:number)=>setMediaIndex(index=>(index+step+media.length)%media.length)
  return <article id={`post-${post.id}`} className={`social-post ${reel?'social-reel':''}`}>
    <header className="social-post-head"><Avatar user={post.author} hasStory={hasStory(post.author.id)} seenStory={storySeen(post.author.id)} onClick={()=>onOpenStory(post.author.id)}/><span><b><button type="button" className="profile-link" onClick={()=>onOpenProfile?.(post.author.username)}>{post.author.displayName}</button></b><small><button type="button" className="profile-link" onClick={()=>onOpenProfile?.(post.author.username)}>@{post.author.username}</button> <i>|</i> {new Date(post.createdAt).toLocaleDateString()}</small></span>{post.author.id===currentUserId&&<button className="post-delete" onClick={onDelete} aria-label="Delete your post" title="Delete post"><Trash2 size={16}/></button>}</header>
    {post.caption&&<p className="social-post-caption">{post.caption}</p>}
    {media.length>0&&<div className="social-post-media" onTouchStart={event=>{touchStart.current=event.touches[0]?.clientX??null}} onTouchEnd={event=>{const start=touchStart.current;const end=event.changedTouches[0]?.clientX;if(start!==null&&end!==undefined&&Math.abs(start-end)>45)moveMedia(start>end?1:-1);touchStart.current=null}}>{media[mediaIndex]?.type==='video'?<video key={media[mediaIndex].url} src={media[mediaIndex].url} controls playsInline preload="metadata"/>:<img key={media[mediaIndex].url} src={media[mediaIndex].url} loading="lazy" alt={`Photo ${mediaIndex+1} of ${media.length} by ${post.author.displayName}`}/>}{media.length>1&&<><button type="button" className="post-carousel-arrow post-carousel-prev" onClick={()=>moveMedia(-1)} aria-label="Previous post media"><ChevronLeft size={20}/></button><button type="button" className="post-carousel-arrow post-carousel-next" onClick={()=>moveMedia(1)} aria-label="Next post media"><ChevronRight size={20}/></button><span className="post-carousel-count">{mediaIndex+1} / {media.length}</span><div className="post-carousel-dots" aria-label={`Media ${mediaIndex+1} of ${media.length}`}>{media.map((item,index)=><button type="button" key={`${item.url}-${index}`} className={index===mediaIndex?'active':''} onClick={()=>setMediaIndex(index)} aria-label={`Show media ${index+1}`}/>)}</div></>}</div>}
    <div className="post-actions"><button className={post.likedByMe?'post-liked':''} onClick={onLike} aria-pressed={post.likedByMe}><Heart size={18} fill={post.likedByMe?'currentColor':'none'}/><span>{post.likesCount} {post.likesCount===1?'Like':'Likes'}</span></button><button onClick={onComments}><MessageCircle size={18}/><span>{post.commentCount} {post.commentCount===1?'Comment':'Comments'}</span></button><button onClick={onShare}><Share2 size={18}/><span>{post.shareCount} {post.shareCount===1?'Share':'Shares'}</span></button></div>
    {commentsOpen&&<div className="post-comments">{comments.map(comment=><div className={`post-comment ${comment.parentCommentId?'reply':''}`} key={comment.id}>
  <Avatar user={comment.author} hasStory={hasStory(comment.author.id)} seenStory={storySeen(comment.author.id)} onClick={()=>onOpenStory(comment.author.id)}/>
  <div className="post-comment-body"><div className="post-comment-bubble-row"><p><b><button type="button" className="profile-link" onClick={()=>onOpenProfile?.(comment.author.username)}>{comment.author.displayName}</button></b> {comment.text}</p>{(comment.author.id===currentUserId||post.author.id===currentUserId)&&<div className="post-comment-menu"><button type="button" aria-label="Comment options" aria-expanded={commentMenuId===comment.id} onClick={()=>setCommentMenuId(value=>value===comment.id?null:comment.id)}><MoreHorizontal size={17}/></button>{commentMenuId===comment.id&&<div className="post-comment-menu-popover" role="menu"><button type="button" role="menuitem" onClick={()=>{setCommentMenuId(null);onDeleteComment(comment)}}><Trash2 size={14}/> Delete comment</button></div>}</div>}</div>
  <div className="post-comment-actions"><button type="button" className={comment.likedByMe?'liked':''} aria-pressed={comment.likedByMe} onClick={()=>onLikeComment(comment)}><Heart size={13} fill={comment.likedByMe?'currentColor':'none'}/><span>{comment.likesCount||0}</span></button><button type="button" onClick={()=>setReplyTarget(comment)}><Reply size={13}/> Reply</button></div></div>
</div>)}{!comments.length&&<small className="no-comments">Be the first to comment.</small>}{replyTarget&&<div className="post-replying"><span>Replying to <b>{replyTarget.author.displayName}</b></span><button type="button" onClick={()=>setReplyTarget(null)} aria-label="Cancel reply"><X size={14}/></button></div>}<form onSubmit={event=>{onComment(event,replyTarget?.id);setReplyTarget(null)}}><input value={commentDraft} onChange={event=>onDraft(event.target.value)} maxLength={1000} placeholder={replyTarget?`Reply to ${replyTarget.author.displayName}...`:'Write a comment...'} aria-label={replyTarget?'Write a reply':'Write a comment'}/><button type="submit" disabled={!commentDraft.trim()||commentSending} aria-label={replyTarget?'Send reply':'Send comment'}><Send size={16}/></button></form></div>}
  </article>
}
function ChatAttachment({url,mediaType,fileName,token}:{url:string;mediaType:'image'|'video'|'file';fileName?:string;token:string}){const [src,setSrc]=useState('');const [failed,setFailed]=useState(false);const [visible,setVisible]=useState(false);const placeholder=useRef<HTMLSpanElement>(null);useEffect(()=>{const node=placeholder.current;if(!node){setVisible(true);return}if(!('IntersectionObserver'in window)){setVisible(true);return}const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){setVisible(true);observer.disconnect()}},{rootMargin:'160px'});observer.observe(node);return()=>observer.disconnect()},[]);useEffect(()=>{if(!visible)return;let objectUrl='';let alive=true;setSrc('');setFailed(false);fetch(url,{headers:{Authorization:`Bearer ${token}`}}).then(response=>{if(!response.ok)throw new Error('Attachment unavailable');return response.blob()}).then(blob=>{if(!alive)return;objectUrl=URL.createObjectURL(blob);setSrc(objectUrl)}).catch(()=>{if(alive)setFailed(true)});return()=>{alive=false;if(objectUrl)URL.revokeObjectURL(objectUrl)}},[url,token,visible]);if(failed)return <small className="chat-media-unavailable">Attachment unavailable</small>;if(!src)return <span ref={placeholder} className="chat-media-loading">{visible?mediaType==='file'?'Downloading file...':'Loading media...':mediaType==='file'?fileName||'File attachment':'Photo or video'}</span>;if(mediaType==='file')return <a className="chat-message-file" href={src} download={fileName||'download'}><Paperclip size={16}/><span>{fileName||'Download file'}</span><small>Download</small></a>;return mediaType==='video'?<video className="chat-message-media" src={src} controls playsInline preload="metadata"/>:<a className="chat-message-image-link" href={src} target="_blank" rel="noreferrer"><img className="chat-message-media" src={src} alt="Shared photo"/></a>}

const CUSTOM_COLOR_SWATCHES=['#7c5cff','#9b6bff','#d84de6','#ff4f83','#ff553e','#ff8738','#ffc857','#f2df55','#72d65c','#22c995','#38c8c8','#35a7ff','#5278ed','#718096','#3b3b48','#12131a','#ffffff','#f0a7c0']
function hexToHsl(hex:string){const match=/^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);if(!match)return{h:264,s:68,l:62};const r=parseInt(match[1],16)/255,g=parseInt(match[2],16)/255,b=parseInt(match[3],16)/255,max=Math.max(r,g,b),min=Math.min(r,g,b),delta=max-min;let h=0;if(delta){if(max===r)h=((g-b)/delta)%6;else if(max===g)h=(b-r)/delta+2;else h=(r-g)/delta+4;h=Math.round(h*60);if(h<0)h+=360}const l=(max+min)/2,sat=delta?delta/(1-Math.abs(2*l-1)):0;return{h,s:Math.round(sat*100),l:Math.round(l*100)}}
function hslToHex(h:number,s:number,l:number){const a=s*Math.min(l,100-l)/100/100;const f=(n:number)=>{const k=(n+h/30)%12,color=l/100-a*Math.max(-1,Math.min(k-3,9-k,1));return Math.round(255*color).toString(16).padStart(2,'0')};return `#${f(0)}${f(8)}${f(4)}`}
function CustomColorPicker({label,value,onChange}:{label:string;value:string;onChange:(color:string)=>void}){const [open,setOpen]=useState(false);const hsl=hexToHsl(value);const change=(h:number,s:number,l:number)=>onChange(hslToHex(h,s,l));return <div className="custom-color-picker"><button type="button" className="custom-color-trigger" aria-label={`Choose ${label}`} aria-expanded={open} onClick={()=>setOpen(state=>!state)}><i style={{backgroundColor:value}}/><span>{value.toUpperCase()}</span><ChevronDown size={14}/></button>{open&&<div className="custom-color-popover" role="dialog" aria-label={`${label} palette`}><header><span><b>{label}</b><small>Pick a preset or fine-tune</small></span><button type="button" aria-label="Close color palette" onClick={()=>setOpen(false)}><X size={15}/></button></header><div className="custom-color-swatches">{CUSTOM_COLOR_SWATCHES.map(color=><button type="button" key={color} aria-label={`Use ${color}`} title={color} className={value.toLowerCase()===color?'selected':''} style={{backgroundColor:color}} onClick={()=>onChange(color)}/>)}</div><label><span>Hue <b>{hsl.h} deg</b></span><input aria-label={`${label} hue`} type="range" min="0" max="360" value={hsl.h} onChange={event=>change(Number(event.target.value),hsl.s,hsl.l)} style={{'--color-hue':hsl.h} as CSSProperties}/></label><label><span>Saturation <b>{hsl.s}%</b></span><input aria-label={`${label} saturation`} type="range" min="0" max="100" value={hsl.s} onChange={event=>change(hsl.h,Number(event.target.value),hsl.l)}/></label><label><span>Brightness <b>{hsl.l}%</b></span><input aria-label={`${label} brightness`} type="range" min="8" max="92" value={hsl.l} onChange={event=>change(hsl.h,hsl.s,Number(event.target.value))}/></label><button type="button" className="custom-color-done" onClick={()=>setOpen(false)}>Done</button></div>}</div>}

function accountAnniversary(createdAt?:string|null){if(!createdAt)return null;const created=new Date(createdAt);if(!Number.isFinite(created.getTime()))return null;const days=Math.max(0,Math.floor((Date.now()-created.getTime())/86400000));const tier=days>=365?'diamond':days>=90?'purple':days>=60?'silver':days>=30?'bronze':'new';return{days,tier}}

function MessageBody({text}:{text:string}){return <>{text.split(/(\n|https?:\/\/[^\s]+)/g).map((part,index)=>part==='\n'?<br key={index}/>:/^https?:\/\//i.test(part)?<a key={index} href={part} target="_blank" rel="noreferrer">{part}</a>:part)}</>}
function SharePostDialog({post,chats,query,loading,sendingChatId,onQuery,onClose,onShareChat,onCopyLink,onExternalShare}:{post:SocialPost;chats:Chat[];query:string;loading:boolean;sendingChatId:string|null;onQuery:(value:string)=>void;onClose:()=>void;onShareChat:(chat:Chat)=>void;onCopyLink:()=>void;onExternalShare:()=>void}){const normalized=query.trim().toLowerCase();const filtered=chats.filter(chat=>!chat.blocked&&!chat.unavailable&&!chat.needsReconnect&&`${chat.isGroup?chat.groupName||'Group chat':chat.user.displayName} ${chat.user.username}`.toLowerCase().includes(normalized));return <div className="share-post-overlay" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget&&!sendingChatId)onClose()}}><section className="share-post-dialog" role="dialog" aria-modal="true" aria-label="Share to a chat"><header><span><small>SHARE FROM SOCIAL LAND</small><b>Send to a chat</b></span><button type="button" onClick={onClose} disabled={!!sendingChatId} aria-label="Close"><X size={18}/></button></header><div className="share-post-preview"><b>{post.kind==='reel'?'Reel':post.kind==='note'?'Note':'Post'} by {post.author.displayName}</b><p>{post.caption||'Open this on Social Land.'}</p></div><label className="share-chat-search"><Search size={16}/><input value={query} onChange={event=>onQuery(event.target.value)} placeholder="Find a person or group" aria-label="Find a person or group"/></label><div className="share-chat-list">{loading?<p className="share-chat-status">Loading your chats...</p>:filtered.length?filtered.map(chat=><button type="button" key={chat.id} disabled={!!sendingChatId} onClick={()=>onShareChat(chat)}><Avatar user={chat.user}/><span><b>{chat.isGroup?chat.groupName||'Group chat':chat.user.displayName}</b><small>{chat.isGroup?'Group chat':`@${chat.user.username}`}</small></span>{sendingChatId===chat.id?<small>Sending...</small>:<Send size={16}/>}</button>):<p className="share-chat-status">{chats.length?'No chats match that search.':'No chats available yet.'}</p>}</div><footer><button type="button" onClick={onCopyLink} disabled={!!sendingChatId}><Link2 size={15}/> Copy link</button>{typeof navigator!=='undefined'&&'share'in navigator&&<button type="button" onClick={onExternalShare} disabled={!!sendingChatId}><Share2 size={15}/> More sharing options</button>}</footer></section></div>}
function Avatar({user,large=false,hasStory=false,seenStory=false,onClick}:{user:User;large?:boolean;hasStory?:boolean;seenStory?:boolean;onClick?:()=>void}){const border=resolveAvatarBorder(user.avatarBorder);const color=user.avatarBorderColor||border?.primary;const borderStyle=border&&color?({'--avatar-frame-primary':color,'--avatar-frame-secondary':`color-mix(in srgb, ${color} 48%, white)`,'--avatar-frame-glow':`color-mix(in srgb, ${color} 72%, transparent)`} as CSSProperties):undefined;const avatar=<div className={'avatar avatar-'+avatarColor(user.username)+' '+(large?'large-avatar':'')+' '+(hasStory?'story-ring':'')+' '+(hasStory&&seenStory?'story-seen':'')+' '+(border?'avatar-bordered avatar-frame-'+border.effect:'')} style={borderStyle}>{user.avatarUrl?<img className="avatar-photo" src={user.avatarUrl} alt=""/>:initials(user.displayName)}</div>;return onClick?<button type="button" className="avatar-trigger" onClick={onClick} aria-label={hasStory?'View '+user.displayName+'s story':user.displayName+'s profile'}>{avatar}</button>:avatar}

function ProfileBio({text,onMention}:{text:string;onMention:(username:string)=>void}){const parts=text.split(/(@[a-z0-9_]{3,24})/gi);return <p className="profile-bio">{parts.map((part,index)=>part.startsWith('@')?<button type="button" className="profile-mention" key={`${part}-${index}`} onClick={()=>onMention(part.slice(1))}>{part}</button>:part)}</p>}

function ProfileDetails({user,onMention,compact=false}:{user:User;onMention?:(username:string)=>void;compact?:boolean}){if(compact)return <span className="profile-details">{(user.location||user.pronouns)&&<small className="profile-meta">{user.location&&<><MapPin size={12}/>{user.location}</>}{user.location&&user.pronouns&&<i>|</i>}{user.pronouns&&user.pronouns}</small>}{user.website&&<a className="profile-meta" href={user.website} target="_blank" rel="noreferrer"><Link2 size={12}/>{user.website.replace(/^https?:\/\//,'')}</a>}</span>;return <div className="profile-details profile-details-expanded">{user.age&&<span className="profile-detail-item"><small>Age</small><b>{user.age}</b></span>}{user.location&&<span className="profile-detail-item"><small>Location</small><b>{user.location}</b></span>}{user.hobbies&&<span className="profile-detail-item"><small>Hobbies</small><b>{user.hobbies}</b></span>}{(user.relationshipStatus||user.relationWith)&&<span className="profile-detail-item relationship-detail"><small>Relationship status</small><span className="relationship-value">{user.relationshipStatus&&<b>{user.relationshipStatus}</b>}{user.relationshipStatus&&user.relationWith&&<i>{String.fromCharCode(183)}</i>}{user.relationWith&&(onMention?<ProfileBio text={user.relationWith} onMention={onMention}/>:<b>{user.relationWith}</b>)}</span></span>}{user.favoriteGame&&<span className="profile-detail-item"><small>Favorite game</small><b>{user.favoriteGame}</b></span>}{user.website&&<a className="profile-detail-item profile-website-detail" href={user.website} target="_blank" rel="noreferrer"><small>Website</small><b><Link2 size={12}/>{user.website.replace(/^https?:\/\//,'')}</b></a>}</div>}

function BlockConfirmDialog({user,blocked,busy,onClose,onConfirm}:{user:User;blocked:boolean;busy:boolean;onClose:()=>void;onConfirm:()=>void}){return <div className="block-confirm-overlay" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget&&!busy)onClose()}}><section className="block-confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="block-confirm-title"><span className="block-confirm-icon"><UserRound size={23}/></span><button type="button" className="block-confirm-close" onClick={onClose} disabled={busy} aria-label="Close"><X size={18}/></button><small className="block-confirm-eyebrow">PRIVACY CONTROL</small><h2 id="block-confirm-title">{blocked?`Unblock ${user.displayName}?`:`Block ${user.displayName}?`}</h2><p>{blocked?`${user.displayName} can find your profile, message, and call you again.`:`They will not be able to message or call you, see your profile, or find you in search. Your friendship and follow connection will be removed.`}</p><div className="block-confirm-actions"><button type="button" className="block-confirm-cancel" onClick={onClose} disabled={busy}>Cancel</button><button type="button" className={blocked?'block-confirm-submit unblock':'block-confirm-submit'} onClick={onConfirm} disabled={busy}>{busy?'Updating':blocked?'Unblock':'Block account'}</button></div></section></div>}
function DeleteChatConfirmDialog({name,onCancel,onConfirm}:{name:string;onCancel:()=>void;onConfirm:()=>void}){return <div className="block-confirm-overlay" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)onCancel()}}><section className="block-confirm-dialog" role="dialog" aria-modal="true" aria-labelledby="delete-chat-title"><span className="block-confirm-icon delete-chat-confirm-icon"><Trash2 size={22}/></span><button type="button" className="block-confirm-close" onClick={onCancel} aria-label="Close"><X size={18}/></button><small className="block-confirm-eyebrow">DELETE CHAT</small><h2 id="delete-chat-title">Delete this chat?</h2><p>The conversation with {name} and its messages will be removed from your chat list. This will not unblock them.</p><div className="block-confirm-actions"><button type="button" className="block-confirm-cancel" onClick={onCancel}>Keep chat</button><button type="button" className="block-confirm-submit" onClick={onConfirm}>Delete chat</button></div></section></div>}
