function DeleteCommentConfirmDialog({busy,onCancel,onConfirm}:{busy:boolean;onCancel:()=>void;onConfirm:()=>void}){return <div className="custom-prompt-overlay" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget&&!busy)onCancel()}}><section className="custom-prompt-dialog" role="alertdialog" aria-modal="true" aria-labelledby="delete-comment-title"><span className="custom-prompt-icon is-danger"><Trash2 size={21}/></span><button type="button" className="custom-prompt-close" onClick={onCancel} disabled={busy} aria-label="Close"><X size={18}/></button><small className="custom-prompt-eyebrow">SOCIAL LAND</small><h2 id="delete-comment-title">Delete this comment?</h2><p>This comment and any replies to it will be permanently deleted.</p><div className="custom-prompt-actions"><button type="button" className="custom-prompt-cancel" onClick={onCancel} disabled={busy}>Keep comment</button><button type="button" className="custom-prompt-submit danger" onClick={onConfirm} disabled={busy}>{busy?'Deleting...':'Delete comment'}</button></div></section></div>}
function CustomPromptDialog({prompt,onCancel,onSubmit}:{prompt:CustomPromptOptions;onCancel:()=>void;onSubmit:(value:string)=>void}){const [value,setValue]=useState(prompt.initialValue||'');const [validationError,setValidationError]=useState('');const inputRef=useRef<HTMLInputElement|HTMLTextAreaElement|null>(null);useEffect(()=>{inputRef.current?.focus();if(prompt.initialValue)inputRef.current?.select()},[prompt]);useEffect(()=>{const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape')onCancel()};window.addEventListener('keydown',closeOnEscape);return()=>window.removeEventListener('keydown',closeOnEscape)},[onCancel]);return <div className="custom-prompt-overlay" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget)onCancel()}}><section className="custom-prompt-dialog" role="dialog" aria-modal="true" aria-labelledby="custom-prompt-title" aria-describedby="custom-prompt-description"><span className={prompt.danger?'custom-prompt-icon is-danger':'custom-prompt-icon'}>{prompt.danger?<Trash2 size={21}/>:<MessageCircle size={21}/>}</span><button type="button" className="custom-prompt-close" onClick={onCancel} aria-label="Close"><X size={18}/></button><small className="custom-prompt-eyebrow">SOCIAL LAND</small><h2 id="custom-prompt-title">{prompt.title}</h2><p id="custom-prompt-description">{prompt.description}</p><form onSubmit={event=>{event.preventDefault();if(prompt.required&&!value.trim()){setValidationError('Please enter a value before continuing.');return}setValidationError('');onSubmit(value)}}>{prompt.input!==false&&(prompt.multiline?<textarea ref={inputRef as React.RefObject<HTMLTextAreaElement>} value={value} onChange={event=>setValue(event.target.value)} placeholder={prompt.placeholder} maxLength={1200} rows={4}/>:<input ref={inputRef as React.RefObject<HTMLInputElement>} value={value} onChange={event=>setValue(event.target.value)} placeholder={prompt.placeholder} maxLength={160} />)}{validationError&&<small className="custom-prompt-validation" role="alert">{validationError}</small>}<div className="custom-prompt-actions"><button type="button" className="custom-prompt-cancel" onClick={onCancel}>{prompt.cancelLabel||'Cancel'}</button><button type="submit" className={prompt.danger?'custom-prompt-submit danger':'custom-prompt-submit'}>{prompt.confirmLabel}</button></div></form></section></div>}
function PartyInviteCard({invite,currentUserId,onJoin}:{invite:PartyInvite;currentUserId:string;onJoin:()=>void}){const invited=invite.invitedIds.includes(currentUserId);const joined=invite.participantIds.includes(currentUserId);return <div className="chat-game-invite party-chat-invite"><b><Video size={15}/> Watch room invitation</b><small>{invite.hostName} invited friends Â· {invite.participantIds.length} watching</small>{invite.status==='open'&&invited&&<button type="button" onClick={onJoin}>{joined?'Open watch room':'Join watch room'}</button>}{invite.status==='ended'&&<small>This room has ended.</small>}</div>}
function GameInviteCard({invite,currentUserId,onAccept,onDecline,onJoin}:{invite:GameInvite;currentUserId:string;onAccept:()=>void;onDecline:()=>void;onJoin:()=>void}){const invited=invite.invitedIds.includes(currentUserId);const joined=invite.playerIds.includes(currentUserId);const title=invite.game==='tic-tac-toe'?'Tic Tac Toe':invite.game==='chess'?'Chess':'Ludo';return <div className="chat-game-invite"><b><Gamepad2 size={15}/> {title} invitation</b><small>{invite.hostName} invited friends. {invite.playerIds.length}/{invite.maxPlayers} joined</small>{invite.status==='open'&&invited&&!joined&&<span><button type="button" onClick={onAccept}>Accept</button><button type="button" onClick={onDecline}>Decline</button></span>}{invite.status==='open'&&joined&&<small>Accepted. Waiting for host to start</small>}{invite.status==='open'&&invited&&!joined&&invite.playerIds.length>=invite.maxPlayers&&<small>Game is full. Join closed</small>}{invite.status==='open'&&!invited&&<small>This invitation is no longer active</small>}{invite.status==='started'&&joined&&<button type="button" onClick={onJoin}>Join game</button>}{invite.status==='started'&&!joined&&<small>Game started. Join closed</small>}{invite.status==='ended'&&<small>Game ended. Join closed</small>}</div>}
function GameAssetLoader({game,progress}:{game:GameKind;progress:number}){return <div className="game-loader"><div className="game-loader-world"><div className="game-loader-platform"/><div className="game-loader-piece">{game==='chess'?'â™ž':game==='ludo'?'â—':'âœ¦'}</div></div><small>PREPARING GAME</small><b>{game==='chess'?'Chess':game==='ludo'?'Ludo':'Tic Tac Toe'} arena</b><span>Loading board, pieces and lighting...</span><div className="game-load-track"><i style={{width:`${progress}%`}}/></div><small>{Math.round(progress)}% READY</small></div>}
function GameLiveControls({voiceState,voiceMuted,voiceCount,chatOpen,isFullscreen,onFullscreen,onVoice,onMute,onChat,onResign,onExit}:{voiceState:'off'|'connecting'|'on';voiceMuted:boolean;voiceCount:number;chatOpen:boolean;isFullscreen:boolean;onFullscreen:()=>void;onVoice:()=>void;onMute:()=>void;onChat:()=>void;onResign:()=>void;onExit:()=>void}){return <nav className="game-live-controls" aria-label="Game controls"><div className="game-live-status"><i/> LIVE GAME <small>{voiceState==='on'?`${voiceCount} in voice`:voiceState==='connecting'?'Connecting voice':'Your turn awaits'}</small></div><div className="game-live-actions"><button type="button" onClick={onVoice}>{voiceState==='on'?'Leave voice':voiceState==='connecting'?'Connecting...':'Join voice'}</button>{voiceState==='on'&&<button type="button" onClick={onMute}>{voiceMuted?'Unmute':'Mute'}</button>}<button type="button" aria-pressed={chatOpen} onClick={onChat}>{chatOpen?'Hide chat':'Text chat'}</button><button type="button" onClick={onFullscreen}>{isFullscreen?<><Minimize2 size={14}/> Window</>:<><Maximize2 size={14}/> Full screen</>}</button><button type="button" className="resign" onClick={onResign}>Resign</button><button type="button" className="exit" onClick={onExit}>Exit</button></div></nav>}
function GameTextChat({messages,userId,draft,onDraft,onSend}:{messages:GameChatLine[];userId:string;draft:string;onDraft:(value:string)=>void;onSend:(event:FormEvent)=>void}){return <aside className="game-text-chat"><header>Game chat <small>Players only</small></header><div className="game-chat-log">{messages.map(message=><p key={message.id} className={message.userId===userId?'mine':''}><b>{message.displayName}</b><span>{message.text}</span></p>)}</div><form onSubmit={onSend}><input value={draft} maxLength={500} onChange={event=>onDraft(event.target.value)} placeholder="Message players..."/><button type="submit" disabled={!draft.trim()}>Send</button></form></aside>}function RealHeading({kicker,title,sub,action}:{kicker:string;title:string;sub:string;action?:ReactNode}){return <div className="real-heading"><div><small>{kicker}</small><h1>{title}</h1><p>{sub}</p></div>{action}</div>}

function UserCard({user,onRequest,onAccept,onChat,onCall,hasStory,storySeen,onOpenStory,onOpenProfile,onFollow,onApproveFollow,onRejectFollow}:{user:User;onRequest?:()=>void;onFollow?:()=>void;onApproveFollow?:()=>void;onRejectFollow?:()=>void;onAccept?:()=>void;onChat?:()=>void;onCall?:()=>void;hasStory?:boolean;storySeen?:boolean;onOpenStory?:()=>void;onOpenProfile?:(username:string)=>void}){return <article className="user-card"><Avatar user={user} hasStory={hasStory} seenStory={storySeen} onClick={onOpenStory}/><span className="user-card-copy"><b><button type="button" className="profile-link" onClick={()=>onOpenProfile?.(user.username)}>{user.displayName}</button></b><small><button type="button" className="profile-link" onClick={()=>onOpenProfile?.(user.username)}>@{user.username}</button></small>{user.suggestionReason&&<small className="suggestion-reason">{user.suggestionReason}</small>}{user.bio&&<p>{user.bio}</p>}<ProfileDetails user={user} compact/></span><div className="user-card-actions">{onFollow&&<button type="button" className="real-button" onClick={onFollow}>{user.isFollowing?"Following":user.isFollowRequested?"Requested":"Follow"}</button>}{onApproveFollow&&<button type="button" className="real-button" onClick={onApproveFollow}><Check size={14}/> Approve follow</button>}{onRejectFollow&&<button type="button" className="real-button outline" onClick={onRejectFollow}>Decline</button>}{onRequest&&user.relationship!=='friend'&&<button className="real-button" disabled={user.relationship==='sent'} onClick={onRequest}>{user.relationship==='sent'?'Request sent':user.relationship==='received'?'Accept request':<><Plus size={14}/> Add friend</>}</button>}{onAccept&&<button className="real-button" onClick={onAccept}><Check size={14}/> Accept</button>}{onChat&&<button className="real-button outline" onClick={onChat}><MessageCircle size={15}/> Message</button>}{onCall&&<button className="real-button outline" onClick={onCall}><Video size={15}/> Call</button>}</div></article>}



function YouTubeEmbed({videoId,interactive,onReady,onStateChange,onError}:{videoId:string;interactive:boolean;onReady:(player:YouTubePlayer|null)=>void;onStateChange:(state:number)=>void;onError:(code:number|string)=>void}){

 const host=useRef<HTMLDivElement>(null);const callbacks=useRef({onReady,onStateChange,onError});callbacks.current={onReady,onStateChange,onError}

 useEffect(()=>{let cancelled=false;let player:YouTubePlayer|null=null;loadYouTubeApi().then(api=>{if(cancelled||!host.current)return;player=new api.Player(host.current,{width:'100%',height:'100%',videoId,playerVars:{playsinline:1,origin:window.location.origin,enablejsapi:1,controls:1,fs:0},events:{onReady:(event:{target:YouTubePlayer})=>callbacks.current.onReady(event.target),onStateChange:(event:{data:number})=>callbacks.current.onStateChange(event.data),onError:(event:{data:number})=>callbacks.current.onError(event.data)}})}).catch(error=>callbacks.current.onError(error instanceof Error?error.message:'YouTube player could not load.'));return()=>{cancelled=true;player?.destroy();callbacks.current.onReady(null)}},[videoId])

 return <div className={"youtube-player-mount"+(interactive?"":" read-only")} ref={host}/>

}



function AuthScreen({onAuth,initialMode,savedAccounts,onSelectSaved,onRemoveSaved}:{onAuth:(token:string,user:User)=>void;initialMode:'login'|'register';savedAccounts:SavedAccount[];onSelectSaved:(account:SavedAccount)=>void;onRemoveSaved:(id:string)=>void}){

 const initialResetToken=new URLSearchParams(window.location.search).get('resetToken')||''
 const [authTheme,setAuthTheme]=useState<'light'|'dark'>(()=>{const saved=localStorage.getItem('social-land-theme');const explicit=localStorage.getItem('social-land-theme-preference')==='explicit'||saved==='dark';return explicit?(saved==='dark'?'dark':'light'):(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')})
 useEffect(()=>{if(localStorage.getItem('social-land-theme-preference')==='explicit'||localStorage.getItem('social-land-theme')==='dark')return;const media=window.matchMedia('(prefers-color-scheme: dark)');const update=()=>setAuthTheme(media.matches?'dark':'light');media.addEventListener('change',update);return()=>media.removeEventListener('change',update)},[])

 const [mode,setMode]=useState<'login'|'register'|'verify-registration'|'verify-login'|'forgot'|'reset'>(initialResetToken?'reset':initialMode);const [accountToRemove,setAccountToRemove]=useState<SavedAccount|null>(null)

 const [identity,setIdentity]=useState('');const [username,setUsername]=useState('');const [displayName,setDisplayName]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [confirmPassword,setConfirmPassword]=useState('');const [resetCode,setResetCode]=useState('');const [resetMaskedEmail,setResetMaskedEmail]=useState('');const [resetCodeVerified,setResetCodeVerified]=useState(false);const [registrationCode,setRegistrationCode]=useState('');const [loginCode,setLoginCode]=useState('');const [loginChallengeToken,setLoginChallengeToken]=useState('');const [loginMaskedEmail,setLoginMaskedEmail]=useState('');const [showPassword,setShowPassword]=useState(false);const [showConfirmPassword,setShowConfirmPassword]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [success,setSuccess]=useState('')

 const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');setSuccess('');try{

  if(mode==='verify-login'){const result=await api<{token:string;user:User}>('/auth/verify-login-code','',{method:'POST',body:JSON.stringify({challengeToken:loginChallengeToken,code:loginCode})});onAuth(result.token,result.user);return}

  if(mode==='forgot'){const d=await api<{maskedEmail?:string}>('/auth/forgot-password','',{method:'POST',body:JSON.stringify({identity:email})});setResetMaskedEmail(d.maskedEmail||'');setResetCode('');setResetCodeVerified(false);setMode('reset');setSuccess('If an account exists, a six-digit reset code will arrive at its saved email address.');return}

  if(mode==='reset'&&!initialResetToken&&!resetCodeVerified){await api('/auth/verify-reset-code','',{method:'POST',body:JSON.stringify({identity:email,code:resetCode})});setResetCodeVerified(true);setSuccess('Code verified. You can now choose a new password.');return}

  if(mode==='reset'){if(password!==confirmPassword)throw new Error('The new passwords do not match.');if(!initialResetToken&&!/^\d{6}$/.test(resetCode))throw new Error('Enter the six-digit code from your email.');const resetResult=await api<{token?:string;user?:User}>('/auth/reset-password','',{method:'POST',body:JSON.stringify(initialResetToken?{token:initialResetToken,password}:{identity:email,code:resetCode,password})});window.history.replaceState({},'',window.location.pathname);if(resetResult.token&&resetResult.user)onAuth(resetResult.token,resetResult.user);else{setMode('login');setPassword('');setConfirmPassword('');setResetCode('');setSuccess('Your password has been reset. Log in with your new password.')}return}

  if(mode==='register'){
   if(password!==confirmPassword)throw new Error('Your passwords do not match.')
   await api('/auth/register/send-code','',{method:'POST',body:JSON.stringify({username,displayName,email})});setRegistrationCode('');setMode('verify-registration');setSuccess('We sent a six-digit verification code to your email. It expires in 10 minutes.');return
  }
  if(mode==='verify-registration'){
   await api('/auth/register/verify-code','',{method:'POST',body:JSON.stringify({email,code:registrationCode})})
   const d=await api<{token:string;user:User}>('/auth/register','',{method:'POST',body:JSON.stringify({username,displayName,email,password})});onAuth(d.token,d.user);return
  }

  const d=await api<{token?:string;user?:User;twoStepRequired?:boolean;challengeToken?:string;maskedEmail?:string}>('/auth/login','',{method:'POST',body:JSON.stringify({identity,password})});if(d.twoStepRequired&&d.challengeToken){setLoginChallengeToken(d.challengeToken);setLoginMaskedEmail(d.maskedEmail||'your primary email');setLoginCode('');setPassword('');setMode('verify-login');setSuccess('A sign-in code was sent to '+(d.maskedEmail||'your primary email')+'. It expires in 10 minutes.');return}if(!d.token||!d.user)throw new Error('Sign-in did not complete. Please try again.');onAuth(d.token,d.user)

 }catch(e){setError((e as Error).message)}finally{setBusy(false)}}

 const heading=mode==='register'?'Find your people.':mode==='verify-registration'?'Verify your email.':mode==='login'?'Welcome back.':mode==='verify-login'?'Check your email.':mode==='forgot'?'Reset your password.':!initialResetToken&&!resetCodeVerified?'Verify your email.':'Choose a new password.'

 const sub=mode==='register'?'Create your Social Land account and start building your circle.':mode==='verify-registration'?'Enter the six-digit code sent to '+email+'. Your account will be created after verification.':mode==='login'?'Log in and pick up right where you left off.':mode==='verify-login'?'Enter the six-digit sign-in code sent to '+loginMaskedEmail+'. It expires after 10 minutes.':mode==='forgot'?'Enter your email address or username. We will send a six-digit reset code.':!initialResetToken&&!resetCodeVerified?'Enter the six-digit code from your email. It expires after 10 minutes.':initialResetToken?'This legacy reset link is valid for 30 minutes.':'Your code is verified. Choose a new password.'

 return <div className={"auth-page auth-theme-"+authTheme}><div className="auth-side"><button className="brand" onClick={()=>location.reload()}><span className="brand-mark"><Sparkles size={19}/></span><span>Social Land</span></button><div className="auth-art"><div className="auth-art-orb">&#10022;</div><div className="auth-art-ball">&#9679;</div><span className="auth-art-message">Hey, you're here <b>&#9829;</b></span><i>&#10022;</i><span className="auth-art-sparkle">&#10023;</span></div><div className="auth-side-copy"><span>YOUR PEOPLE, CLOSE BY</span><h2>Good things<br/>happen <em>together.</em></h2><p>One cozy corner for conversations, games, and little moments with your people.</p><div className="auth-trust"><Check size={14}/> Make your circle yours</div></div><div className="auth-side-footer">Your people, together. <span>&#10022;</span></div></div><main className="auth-main"><div className="auth-mobile-brand"><span className="brand-mark"><Sparkles size={19}/></span>Social Land</div><div className="auth-form-wrap"><div className="auth-kicker">{mode==='register'?'COME ON IN':mode==='verify-registration'?'EMAIL VERIFICATION':mode==='login'?'GOOD TO HAVE YOU BACK':mode==='verify-login'?'TWO-STEP VERIFICATION':'ACCOUNT SECURITY'}</div><h1>{heading}</h1><p className="auth-sub">{sub}</p>{error&&<div className="auth-error">{error}</div>}{success&&<div className="auth-success">{success}</div>}{mode==='login'&&savedAccounts.length>0&&<section className="saved-account-list auth-saved-account-list"><h2>Saved accounts</h2>{savedAccounts.map(account=><article className="saved-account-row" key={account.id}><button type="button" className="saved-account-switch" onClick={()=>onSelectSaved(account)}><span className="saved-account-avatar">{account.avatarUrl?<img src={account.avatarUrl} alt=""/>:initials(account.displayName)}</span><span className="saved-account-copy"><b>{account.displayName}</b><small>@{account.username}</small></span><span className="saved-account-action">Switch</span></button><button type="button" className="saved-account-remove" aria-label={`Remove saved account @${account.username}`} onClick={()=>setAccountToRemove(account)}><X size={16}/></button></article>)}</section>}<form className="auth-form" onSubmit={submit}>

 {mode==='register'?<><label>YOUR NAME<input required value={displayName} onChange={e=>setDisplayName(e.target.value)} placeholder="What should we call you?" maxLength={50}/></label><label>CHOOSE A USERNAME<div className="username-field"><span>@</span><input required minLength={3} maxLength={24} pattern="[A-Za-z0-9_]+" value={username} onChange={e=>setUsername(e.target.value)} placeholder="yourname"/></div><small>Letters, numbers, and underscores. At least 3 characters.</small></label><label>EMAIL ADDRESS<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" autoComplete="email"/></label></>:null}

 {mode==='verify-login'?<label>SIGN-IN CODE<input type="text" required inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} value={loginCode} onChange={e=>setLoginCode(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="6-digit code"/></label>:null}
 {mode==='verify-registration'?<><label>6-DIGIT EMAIL CODE<input type="text" required inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} value={registrationCode} onChange={e=>setRegistrationCode(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="Enter verification code"/></label><button type="button" className="auth-forgot" disabled={busy} onClick={async()=>{setBusy(true);setError('');try{await api('/auth/register/send-code','',{method:'POST',body:JSON.stringify({username,displayName,email})});setRegistrationCode('');setSuccess('A new verification code has been sent.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}>Send a new code</button><button type="button" className="auth-forgot" onClick={()=>{setMode('register');setRegistrationCode('');setError('');setSuccess('')}}>Change account details</button></>:null}

 {mode==='login'&&<label>EMAIL OR USERNAME<input required value={identity} onChange={e=>setIdentity(e.target.value)} placeholder="you@example.com or username" autoComplete="username"/></label>}

 {mode==='forgot'&&<label>EMAIL OR USERNAME<input type="text" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com or @username" autoComplete="username"/></label>}

 {mode==='reset' && (!initialResetToken && !resetCodeVerified ? <>
  <label>EMAIL CODE<input type="text" required inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} value={resetCode} onChange={event=>setResetCode(event.target.value.replace(/\D/g,'').slice(0,6))} placeholder="6-digit code"/></label>
  <small>{resetMaskedEmail?'Code sent to '+resetMaskedEmail:'The code will go to the email saved to your account.'}</small>
  <button type="button" className="auth-forgot" onClick={()=>{setMode('forgot');setError('');setSuccess('')}}>Request a new code</button>
 </> : <>
  <label>NEW PASSWORD<span className="auth-password-input"><input type={showPassword?'text':'password'} required minLength={8} maxLength={72} value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters" autoComplete="new-password"/><button type="button" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?'Hide password':'Show password'}>{showPassword?<EyeOff size={16}/>:<Eye size={16}/>}</button></span></label>
  <label>CONFIRM NEW PASSWORD<span className="auth-password-input"><input type={showConfirmPassword?'text':'password'} required minLength={8} maxLength={72} value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} placeholder="Enter it one more time" autoComplete="new-password"/><button type="button" onClick={()=>setShowConfirmPassword(v=>!v)} aria-label={showConfirmPassword?'Hide confirmation password':'Show confirmation password'}>{showConfirmPassword?<EyeOff size={16}/>:<Eye size={16}/>}</button></span></label>
 </>)}
 {(mode==='login' || mode==='register') && <>
  <label>PASSWORD<span className="auth-password-input"><input type={showPassword?'text':'password'} required minLength={mode==='register'?8:1} maxLength={72} value={password} onChange={e=>setPassword(e.target.value)} placeholder={mode==='register'?'At least 8 characters':'Your password'} autoComplete={mode==='register'?'new-password':'current-password'}/><button type="button" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?'Hide password':'Show password'}>{showPassword?<EyeOff size={16}/>:<Eye size={16}/>}</button></span>{mode==='register'&&<small>Use at least 8 characters.</small>}</label>
  {mode==='register'&&<label>CONFIRM PASSWORD<span className="auth-password-input"><input type={showConfirmPassword?'text':'password'} required minLength={8} maxLength={72} value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} placeholder="Enter your password again" autoComplete="new-password"/><button type="button" onClick={()=>setShowConfirmPassword(v=>!v)} aria-label={showConfirmPassword?'Hide confirmation password':'Show confirmation password'}>{showConfirmPassword?<EyeOff size={16}/>:<Eye size={16}/>}</button></span></label>}
  {mode==='login'&&<button type="button" className="auth-forgot" onClick={()=>{setEmail(identity);setMode('forgot');setError('');setSuccess('')}}>Forgot password?</button>}
 </>}

 <button className="auth-submit" disabled={busy}>{busy?'One moment...':mode==='register'?'Create account':mode==='verify-registration'?'Verify and create account':mode==='verify-login'?'Verify and log in':mode==='login'?'Log in':mode==='forgot'?'Send code':mode==='reset'&&!initialResetToken&&!resetCodeVerified?'Verify code':mode==='reset'?'Reset password':'Save new password'}<span>&#8594;</span></button></form>

 <div className="auth-switch">{mode==='register'?'Already have an account?':mode==='login'?'New to Social Land?':mode==='forgot'?'Remembered your password?':mode==='verify-registration'?'Already verified or have an account?':mode==='verify-login'?'Entered the wrong account?':'Need a different account?'} <button type="button" onClick={()=>{if(mode==='verify-login'){setLoginChallengeToken('');setLoginCode('')}setMode(mode==='login'?'register':'login');setError('');setSuccess('')}}>{mode==='register'?'Log in':mode==='login'?'Create an account':'Back to log in'}</button></div>

 {mode==='register'&&<><div className="auth-divider"><span>YOUR SPACE, YOUR PACE</span></div><div className="auth-benefits"><span><Check size={14}/> Your own Social Land ID</span><span><Check size={14}/> Private friend chats</span></div><small className="auth-terms">By continuing, you agree to be kind to one another.</small></>}</div><footer className="auth-mobile-footer">Â© Social Land | Your people, together</footer></main>{accountToRemove&&<SavedAccountRemovalDialog account={accountToRemove} onCancel={()=>setAccountToRemove(null)} onConfirm={()=>{onRemoveSaved(accountToRemove.id);setAccountToRemove(null)}}/>}</div>

}
